select t1.id as level1id,t1.typename as level1name,t23.level2id as level2id ,t23.level2name as level2name, t23.level3id as level3id,t23.level3name as level3name from rpsectype t1,(select t2.id as level2id,t2.fathernode, t2.typename as level2name,t3.id as level3id,t3.typename as level3name from rpsectype t2, (select id,typename,fathernode from rpsectype where tablecode=#{tablecode} and grouplevel=3
) t3 where t3.fathernode=t2.id) t23 where t1.id=t23.fathernode
and id=#{level3id} ) t3 where t3.fathernode=t2.id) t23 where t1.id=t23.fathernode

select * From Rpsectype Where tablecode=#{tableCode} and Id=#{typeCode}
 Union select * From Rpsectype Where tablecode=#{tableCode} and Fathernode=#{typeCode}
 Union select * from Rpsectype where tablecode=#{tableCode} and fathernode in (Select id From Rpsectype Where Fathernode =#{typeCode})
